package edu.riara.edp.week09;
import javafx.application.Application;import javafx.concurrent.*;import javafx.scene.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Stage;
public class ReusableServiceDemo extends Application {private final Service<String> service=new Service<>(){protected Task<String> createTask(){return new Task<>(){protected String call()throws Exception{for(int i=0;i<10;i++){if(isCancelled())return "Cancelled";Thread.sleep(200);}return "Synced";}};}};public void start(Stage s){Label status=new Label("Ready");ProgressIndicator spinner=new ProgressIndicator();spinner.setVisible(false);Button start=new Button("Sync"),cancel=new Button("Cancel");cancel.setDisable(true);service.setOnRunning(e->{status.setText("Syncing");spinner.setVisible(true);start.setDisable(true);cancel.setDisable(false);});service.setOnSucceeded(e->{status.setText(service.getValue());reset(start,cancel,spinner);});service.setOnCancelled(e->{status.setText("Cancelled");reset(start,cancel,spinner);});service.setOnFailed(e->{status.setText("Failed");reset(start,cancel,spinner);});start.setOnAction(e->service.restart());cancel.setOnAction(e->service.cancel());s.setOnCloseRequest(e->service.cancel());s.setScene(new Scene(new VBox(12,start,cancel,spinner,status),400,240));s.show();}private void reset(Button s,Button c,ProgressIndicator p){s.setDisable(false);c.setDisable(true);p.setVisible(false);}public static void main(String[]a){launch(a);}}